import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.C3fpVp7C.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"concepts.md","filePath":"concepts.md","lastUpdated":1792160181000}'),r={name:"concepts.md"};function s(i,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>This page explains the model behind agent-auth: who delegates, what a token carries, how scopes match requests and how authority narrows as it passes from agent to sub-agent.</p><h3 id="principal-agent-and-grant" tabindex="-1">Principal, agent and grant <a class="header-anchor" href="#principal-agent-and-grant" aria-label="Permalink to &quot;Principal, agent and grant&quot;">​</a></h3><p>A <strong>principal</strong> is the person or account that delegates authority, such as <code>alice</code>. An <strong>agent</strong> is the software that acts for them, such as <code>assistant</code>. A <strong>grant</strong> records that a principal gave an agent a set of scopes until a point in time, optionally with a maximum number of uses. Creating a grant returns the grant&#39;s root token. Only the holder of the admin token creates grants.</p><h3 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h3><p>Tokens are compact JWS (JWT) values signed with Ed25519 (<code>alg: EdDSA</code>, <code>typ: agent-auth+jwt</code>). The service publishes its public key at <code>/.well-known/jwks.json</code>.</p><table tabindex="0"><thead><tr><th>Claim</th><th>Meaning</th></tr></thead><tbody><tr><td><code>iss</code></td><td>Issuer URL of the agent-auth service</td></tr><tr><td><code>sub</code></td><td>Agent the token belongs to</td></tr><tr><td><code>prn</code></td><td>Principal that delegated authority</td></tr><tr><td><code>gnt</code></td><td>Grant the token descends from</td></tr><tr><td><code>scp</code></td><td>Scopes in canonical form</td></tr><tr><td><code>jti</code></td><td>Token id</td></tr><tr><td><code>par</code></td><td>Parent token id, for attenuated tokens</td></tr><tr><td><code>dep</code></td><td>Delegation depth; the grant&#39;s root token has depth 0</td></tr><tr><td><code>mxu</code></td><td>Maximum uses, when limited</td></tr><tr><td><code>iat</code>, <code>exp</code></td><td>Issue and expiry times</td></tr></tbody></table><h3 id="scope-grammar" tabindex="-1">Scope grammar <a class="header-anchor" href="#scope-grammar" aria-label="Permalink to &quot;Scope grammar&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;action&gt; [&lt;resource-glob&gt;] [&lt;key&gt;:&lt;glob&gt; ...] [max=&lt;amount&gt;[&lt;CUR&gt;]] [approval=required]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Scope</th><th>Permits</th></tr></thead><tbody><tr><td><code>gmail:send to:*@acme.com</code></td><td>Sending mail when every <code>to</code> recipient ends in <code>@acme.com</code></td></tr><tr><td><code>github:repo:read acme/*</code></td><td>Reading any repository in the <code>acme</code> organization</td></tr><tr><td><code>github:* acme/widgets</code></td><td>Any GitHub action on <code>acme/widgets</code></td></tr><tr><td><code>payments:charge max=50USD</code></td><td>Charges up to 50 USD per request</td></tr><tr><td><code>payments:refund max=500USD approval=required</code></td><td>Refunds up to 500 USD, each approved by a human</td></tr><tr><td><code>fs:read resource:reports:2026</code></td><td>Reading the resource <code>reports:2026</code> (use <code>resource:</code> when the resource contains <code>:</code> or <code>=</code>)</td></tr></tbody></table><p>A request is concrete: an <code>action</code>, an optional <code>resource</code>, optional <code>params</code> (a string or a list of strings per key) and an optional <code>amount</code>.</p><ul><li><strong>Actions</strong> are lowercase segments separated by <code>:</code>. A <code>*</code> segment matches exactly one segment, except in the last position, where it matches one or more. <code>github:*</code> matches <code>github:repo:read</code>; <code>github:*:read</code> does not match <code>github:a:b:read</code>.</li><li><strong>Resources and parameters</strong> use globs in which <code>*</code> matches any run of characters, including <code>/</code>. Matching is case-sensitive. If a scope names a parameter, the request must include it, and every value in a list must match.</li><li><strong>Amounts</strong> must use the same currency as the limit and not exceed it. A request without an amount does not match a scope that has a limit.</li><li><strong>Approval</strong> turns an <code>allow</code> into <code>approval_required</code> until a human approves that exact request.</li></ul><p>A request is allowed when any scope matches it without requiring approval. A denial names the closest scope and the constraint that failed, so an agent can correct its request.</p><h3 id="attenuation" tabindex="-1">Attenuation <a class="header-anchor" href="#attenuation" aria-label="Permalink to &quot;Attenuation&quot;">​</a></h3><p>Any token holder can derive a child token with <code>POST /v1/tokens/attenuate</code>. The service accepts the child only when every child scope is covered by a single parent scope:</p><ul><li>The child&#39;s action pattern matches a subset of the parent&#39;s.</li><li>The child&#39;s resource and parameter globs are subsets of the parent&#39;s. A child may add parameter constraints but never drop one.</li><li>The child&#39;s amount limit uses the same currency and is no higher.</li><li>If the parent scope requires approval, the child scope does too.</li></ul><p>The child also expires no later than its parent, carries a use limit no higher than its parent&#39;s, and sits one level deeper, up to a configurable maximum depth (8 by default). A use of a child token counts against every token above it.</p><p>The glob subset check is conservative: it can reject a few exotic pairs where containment does hold, and it never accepts a pair where it does not. Property-based tests in check that an accepted child set never allows a request that its parent set denies, across chains of attenuations.</p><h3 id="revocation" tabindex="-1">Revocation <a class="header-anchor" href="#revocation" aria-label="Permalink to &quot;Revocation&quot;">​</a></h3><p>Revoking a token revokes all of its descendants. Revoking a grant revokes every token under it. Each check also walks the token&#39;s chain back to the root, so a token whose ancestor is revoked or expired is rejected even if it was issued before the revocation. An agent can revoke its own token by presenting it; revoking an arbitrary token by id requires the admin token.</p><h3 id="approvals" tabindex="-1">Approvals <a class="header-anchor" href="#approvals" aria-label="Permalink to &quot;Approvals&quot;">​</a></h3><p>When a request matches only scopes marked <code>approval=required</code>, <code>check</code> returns <code>approval_required</code> and an approval id. A human approves or denies it with the admin API or <code>agent-auth approve &lt;id&gt;</code>. The agent then repeats the same request with the approval id. An approval covers exactly one request (compared by a hash of its canonical JSON) on one token, and it is consumed on first use.</p><h3 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h3><p>Every grant, attenuation, denied attenuation, revocation, check and approval decision appends an entry to the <code>audit</code> table. Each entry stores <code>hash = sha256(prevHash + &quot;\\n&quot; + canonicalJson({seq, ts, type, actor, data}))</code>, and SQLite triggers reject <code>UPDATE</code> and <code>DELETE</code> on the table. <code>agent-auth audit verify</code> recomputes the chain, either from the API or directly from a database file, and reports the first entry that fails.</p><p>The chain alone cannot tell that entries were removed from the end, or that someone rewrote and rehashed the whole log. To catch that, record the <code>head</code> hash somewhere the service cannot write, and pass it back with <code>--head</code>: verification fails unless that hash is still in the chain.</p><h2 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h2><p>agent-auth limits what a compromised or misbehaving agent can do with delegated authority, and records what it did. It assumes the agent-auth server, its database and its signing key are trusted.</p><p>It helps against:</p><ul><li>An agent, or a prompt injection steering it, attempting actions outside its scopes.</li><li>A sub-agent receiving more authority than the task needs, or widening its own token.</li><li>A leaked agent token being useful for long: tokens expire, can carry use limits, and you can revoke them with their descendants.</li><li>Silent edits to the audit history by someone with database access, provided you verify the chain and anchor the head outside the service.</li></ul><p>Know its limits:</p><ul><li><strong>Tokens are bearer tokens.</strong> Anyone who holds one can use it until it expires or you revoke it. There is no proof of possession yet.</li><li><strong>The admin token is all-powerful.</strong> Anyone with it can create grants and approve requests. Keep it out of agents&#39; reach.</li><li><strong>Enforcement happens where you call <code>check</code>.</strong> A tool server that maps requests to the wrong action or resource, or skips the check, bypasses agent-auth. The credential proxy pattern keeps the real secret away from the agent so that skipping the check is not an option for it.</li><li><strong>Offline verification does not see revocations</strong> until the token expires.</li><li><strong>The audit log is tamper-evident, not tamper-proof.</strong> Someone who can write to the database can delete or rewrite entries; verification detects this, and detecting a rewrite of the latest entries requires an anchored head. Entries are hashed, not signed.</li><li><strong>Use limits count allowed checks</strong>, not successful upstream calls.</li><li><strong>One signing key, no rotation yet.</strong> Replacing the key file invalidates all outstanding tokens.</li><li><strong>No TLS.</strong> The server binds to loopback by default; put a TLS-terminating proxy in front before you expose it.</li><li><strong>Single node.</strong> Storage is one SQLite file.</li><li><strong>Audit entries contain request details</strong>, such as recipients and amounts. Treat the database as sensitive.</li></ul>',31)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
